  method: 'patch',
  maxBodyLength: Infinity,
  url: 'https://192.168.0.1/proxy/network/integration/v1/sites/{siteId}/firewall/policies/{firewallPolicyId}',
  headers: { 
    'Accept': 'application/json', 
    'X-API-Key': '<X-API-Key>', 
    'Content-Type': 'application/json'
  },
  data : data
};

axios.request(config)
.then((response) => {
  console.log(JSON.stringify(response.data));
})
.catch((error) => {
  console.log(error);
});

